import{_ as e,c as a,o as i,a0 as o}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque.","frontmatter":{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque."},"headers":[],"relativePath":"it/blog/pre-shot-routines.md","filePath":"it/blog/pre-shot-routines.md"}');const r=e({name:"it/blog/pre-shot-routines.md"},[["render",function(e,t,r,n,l,s){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="creazione-di-routine-pre-tiro" tabindex="-1">Creazione di routine pre-tiro <a class="header-anchor" href="#creazione-di-routine-pre-tiro" aria-label="Permalink to &quot;Creazione di routine pre-tiro&quot;">​</a></h1><p>La differenza tra un buon lancio e un lancio eccellente spesso si nota prima ancora che la boccia lasci la tua mano. Una routine pre-tiro ben progettata è la tua ancora di salvezza nella tempesta della competizione: una sequenza affidabile che prepara mente e corpo a prestazioni ottimali.</p><h2 id="perche-le-routine-pre-tiro-sono-importanti" tabindex="-1">Perché le routine pre-tiro sono importanti <a class="header-anchor" href="#perche-le-routine-pre-tiro-sono-importanti" aria-label="Permalink to &quot;Perché le routine pre-tiro sono importanti&quot;">​</a></h2><p>Gli atleti d&#39;élite di tutti gli sport utilizzano routine pre-tiro. Nella pétanque, dove ogni tiro è discreto e la pressione può aumentare tra un tiro e l&#39;altro, le routine hanno molteplici scopi:</p><ul><li><strong>Coerenza</strong>: la stessa preparazione porta a un&#39;esecuzione più coerente</li><li><strong>Focus</strong>: Assegna alla tua mente un compito costruttivo invece di preoccuparti</li><li><strong>Transizione</strong>: ti aiuta a passare dal pensare all&#39;agire</li><li><strong>Gestione della pressione</strong>: le azioni familiari calmano il sistema nervoso</li><li><strong>Reset</strong>: cancella lo scatto precedente dalla tua mente</li></ul><h2 id="anatomia-di-una-routine-efficace" tabindex="-1">Anatomia di una routine efficace <a class="header-anchor" href="#anatomia-di-una-routine-efficace" aria-label="Permalink to &quot;Anatomia di una routine efficace&quot;">​</a></h2><p>Una buona routine pre-tiro si compone di tre fasi:</p><h3 id="fase-1-valutazione-5-10-secondi" tabindex="-1">Fase 1: Valutazione (5-10 secondi) <a class="header-anchor" href="#fase-1-valutazione-5-10-secondi" aria-label="Permalink to &quot;Fase 1: Valutazione (5-10 secondi)&quot;">​</a></h3><ul><li>Leggi il terreno</li><li>Visualizza il risultato desiderato</li><li>Scegli il tipo di lancio</li><li>Impegnarsi nella decisione</li></ul><h3 id="fase-2-preparazione-5-10-secondi" tabindex="-1">Fase 2: Preparazione (5-10 secondi) <a class="header-anchor" href="#fase-2-preparazione-5-10-secondi" aria-label="Permalink to &quot;Fase 2: Preparazione (5-10 secondi)&quot;">​</a></h3><ul><li>Prendi la tua posizione</li><li>Trova la tua presa</li><li>Calma il tuo respiro</li><li>Senti il peso della boccia</li></ul><h3 id="fase-3-esecuzione-3-5-secondi" tabindex="-1">Fase 3: Esecuzione (3-5 secondi) <a class="header-anchor" href="#fase-3-esecuzione-3-5-secondi" aria-label="Permalink to &quot;Fase 3: Esecuzione (3-5 secondi)&quot;">​</a></h3><ul><li>Messa a fuoco finale sul bersaglio</li><li>Fidati del tuo corpo</li><li>Liberati senza pensarci</li><li>Seguire con naturalezza</li></ul><h2 id="costruire-la-tua-routine-personale" tabindex="-1">Costruire la tua routine personale <a class="header-anchor" href="#costruire-la-tua-routine-personale" aria-label="Permalink to &quot;Costruire la tua routine personale&quot;">​</a></h2><h3 id="fase-1-osserva-i-tuoi-schemi-attuali" tabindex="-1">Fase 1: osserva i tuoi schemi attuali <a class="header-anchor" href="#fase-1-osserva-i-tuoi-schemi-attuali" aria-label="Permalink to &quot;Fase 1: osserva i tuoi schemi attuali&quot;">​</a></h3><p>Prima di creare una nuova routine, osserva cosa fai già:</p><ul><li>Cosa fai prima di lanciare con successo?</li><li>Cosa cambia quando sei sotto pressione?</li><li>Cosa ti sembra naturale?</li></ul><h3 id="fase-2-progetta-la-tua-sequenza" tabindex="-1">Fase 2: Progetta la tua sequenza <a class="header-anchor" href="#fase-2-progetta-la-tua-sequenza" aria-label="Permalink to &quot;Fase 2: Progetta la tua sequenza&quot;">​</a></h3><p>Crea una routine che includa:</p><p><strong>Elementi fisici:</strong></p><ul><li>Come ti avvicini al cerchio</li><li>Come prendi e tieni la boccia</li><li>La tua posizione e il tuo posizionamento</li><li>Uno schema respiratorio specifico</li></ul><p><strong>Elementi mentali:</strong></p><ul><li>Una visualizzazione del risultato</li><li>Una parola o una frase chiave</li><li>Un punto di impegno (il momento in cui decidi &quot;questo è il lancio&quot;)</li></ul><h3 id="fase-3-semplificare" tabindex="-1">Fase 3: Semplificare <a class="header-anchor" href="#fase-3-semplificare" aria-label="Permalink to &quot;Fase 3: Semplificare&quot;">​</a></h3><p>La tua routine dovrebbe essere:</p><ul><li><strong>Abbastanza breve</strong> da mantenere sotto pressione (15-25 secondi in totale)</li><li><strong>Abbastanza semplice</strong> da ricordare quando sei stressato</li><li><strong>Abbastanza flessibile</strong> da adattarsi a diverse situazioni</li></ul><h2 id="esempi-di-routine" tabindex="-1">Esempi di routine <a class="header-anchor" href="#esempi-di-routine" aria-label="Permalink to &quot;Esempi di routine&quot;">​</a></h2><h3 id="la-routine-del-puntatore" tabindex="-1">La routine del puntatore <a class="header-anchor" href="#la-routine-del-puntatore" aria-label="Permalink to &quot;La routine del puntatore&quot;">​</a></h3><ol><li>Mettiti dietro il cerchio, valuta il terreno</li><li>Visualizza il percorso della boccia e il punto di atterraggio</li><li>Entra nel cerchio, trova la tua posizione</li><li>Tre respiri lenti mentre senti la boule</li><li>Occhi sul bersaglio, rilascio</li></ol><h3 id="la-routine-del-tiratore" tabindex="-1">La routine del tiratore <a class="header-anchor" href="#la-routine-del-tiratore" aria-label="Permalink to &quot;La routine del tiratore&quot;">​</a></h3><ol><li>Identifica la boccia bersaglio, scegli l&#39;angolazione</li><li>Visualizza l&#39;impatto e il risultato</li><li>Entra nel cerchio con uno scopo</li><li>Un respiro profondo, senti il peso</li><li>Fissa lo sguardo sul bersaglio, eseguilo</li></ol><h2 id="errori-comuni-da-evitare" tabindex="-1">Errori comuni da evitare <a class="header-anchor" href="#errori-comuni-da-evitare" aria-label="Permalink to &quot;Errori comuni da evitare&quot;">​</a></h2><h3 id="troppo-lungo" tabindex="-1">Troppo lungo <a class="header-anchor" href="#troppo-lungo" aria-label="Permalink to &quot;Troppo lungo&quot;">​</a></h3><p>Se la tua routine dura più di 30 secondi, stai pensando troppo. Le routine lunghe danno più tempo all&#39;ansia di accumularsi.</p><h3 id="troppo-rigido" tabindex="-1">Troppo rigido <a class="header-anchor" href="#troppo-rigido" aria-label="Permalink to &quot;Troppo rigido&quot;">​</a></h3><p>Se un&#39;interruzione distrugge la tua routine, significa che è troppo fragile. Sviluppa la flessibilità: se qualcosa interrompe la tua concentrazione, crea un trigger di reset.</p><h3 id="saltare-sotto-pressione" tabindex="-1">Saltare sotto pressione <a class="header-anchor" href="#saltare-sotto-pressione" aria-label="Permalink to &quot;Saltare sotto pressione&quot;">​</a></h3><p>La routine è più importante quando la pressione è alta. Se la abbandoni quando sei stressato, perdi i suoi benefici protettivi.</p><h3 id="concentrandosi-sulla-meccanica" tabindex="-1">Concentrandosi sulla meccanica <a class="header-anchor" href="#concentrandosi-sulla-meccanica" aria-label="Permalink to &quot;Concentrandosi sulla meccanica&quot;">​</a></h3><p>La tua routine dovrebbe concludersi concentrandosi sul risultato, non sulla tecnica. &quot;Colpisci il bersaglio&quot; non &quot;tieni il gomito dritto&quot;.</p><h2 id="praticare-la-tua-routine" tabindex="-1">Praticare la tua routine <a class="header-anchor" href="#praticare-la-tua-routine" aria-label="Permalink to &quot;Praticare la tua routine&quot;">​</a></h2><h3 id="in-formazione" tabindex="-1">In formazione <a class="header-anchor" href="#in-formazione" aria-label="Permalink to &quot;In formazione&quot;">​</a></h3><ul><li>Utilizza la tua routine completa per ogni lancio, anche quelli casuali</li><li>Prenditi il tempo necessario per garantire la coerenza</li><li>Esercitati con le distrazioni per sviluppare la resilienza</li></ul><h3 id="costruire-l-39-automaticita" tabindex="-1">Costruire l&#39;automaticità <a class="header-anchor" href="#costruire-l-39-automaticita" aria-label="Permalink to &quot;Costruire l&amp;#39;automaticità&quot;">​</a></h3><p>L&#39;obiettivo è che la tua routine diventi automatica, qualcosa che fai senza pensarci. Questo richiede ripetizione:</p><ul><li>Oltre 100 lanci con la stessa routine</li><li>Utilizzo coerente in diverse situazioni</li><li>Esposizione graduale alla pressione mantenendo la routine</li></ul><h2 id="adattarsi-alla-concorrenza" tabindex="-1">Adattarsi alla concorrenza <a class="header-anchor" href="#adattarsi-alla-concorrenza" aria-label="Permalink to &quot;Adattarsi alla concorrenza&quot;">​</a></h2><p>Durante le partite, la tua routine potrebbe richiedere lievi modifiche:</p><ul><li><strong>Pressione di tempo</strong>: tieni pronta una versione abbreviata</li><li><strong>Condizioni meteorologiche</strong>: adattare gli elementi fisici secondo necessità</li><li><strong>Momenti di alta pressione</strong>: rallenta leggermente, non accelerare</li></ul><h2 id="la-routine-di-reset" tabindex="-1">La routine di reset <a class="header-anchor" href="#la-routine-di-reset" aria-label="Permalink to &quot;La routine di reset&quot;">​</a></h2><p>Altrettanto importante è ciò che fai dopo un lancio:</p><ol><li><strong>Accetta il risultato</strong> — buono o cattivo, è fatta</li><li><strong>Reset fisico</strong> — fai un passo indietro, scrollati di dosso la tensione</li><li><strong>Reset mentale</strong>: libera la mente dal problema del lancio</li><li><strong>Preparati per il prossimo</strong> — sposta l&#39;attenzione su ciò che sta arrivando</li></ol><hr><p>| <em>Correlato: <a href="/it/istruzione/forza-mentale/routine-pre-tiro">Guida alla routine pre-tiro</a> | <a href="/it/educazione/forza-mentale/gestire-la-pressione">Gestire la pressione</a> | <a href="/it/educazione/consapevolezza/tecniche">Tecniche di consapevolezza</a></em> |</p>',54)])])}]]);export{t as __pageData,r as default};
